// Import only the AES cipher + Utf8 encoder, not the whole crypto-js library
// (which also bundles blowfish/tripledes/rabbit/rc4/md5/sha1/sha256/sha512/sha3 — unused here).
export const encodeString = async (data, key) => {
    const AES = await import('crypto-js/aes');
    return AES.encrypt(data, key).toString();
};
export const decodeString = async (encodedData, key) => {
    const [AES, Utf8] = await Promise.all([
        import('crypto-js/aes'),
        import('crypto-js/enc-utf8'),
    ]);
    return AES.decrypt(encodedData, key).toString(Utf8);
};
