import { createSlice } from '@reduxjs/toolkit';
import { generateUUID } from '06_shared/utils/generateUUID';
const initialState = {
    notification_list: [],
    isOpenNotificationList: false,
};
export const notificationSlice = createSlice({
    name: 'notification',
    initialState,
    reducers: {
        addNotificationList: (state, action) => {
            state.notification_list = action.payload;
        },
        addNotificationItem: (state, action) => {
            if (state.notification_list.length === 500) {
                state.notification_list.shift();
            }
            state.notification_list.push({
                ...action.payload,
                uuid: generateUUID(),
                created_at: Date.now(),
                isVisible: true,
            });
        },
        closeNotificationItem: (state, action) => {
            const index = state.notification_list.findIndex(item => item.uuid === action.payload);
            if (index !== -1) {
                state.notification_list[index].isVisible = false;
            }
        },
        changeIsOpenNotificationList: (state, action) => {
            state.isOpenNotificationList = action.payload;
        },
        resetNotificationSlice() {
            return initialState;
        },
    },
});
export const { actions: notificationActions } = notificationSlice;
export const { reducer: notificationReducer } = notificationSlice;
