import { useCallback } from 'react';
import { useGetTradePreferencesInServerSide } from './useGetTradePreferencesInServerSide';
// Picks the client- or server-side implementation of an action based on the
// user's trade_in_server_side preference, so callers don't each re-implement
// their own {0: client, 1: server} lookup for the same flag.
const useTradeSideExecutor = (clientFn, serverFn) => {
    const trade_in_server_side = useGetTradePreferencesInServerSide();
    return useCallback((...args) => (trade_in_server_side ? serverFn(...args) : clientFn(...args)), [trade_in_server_side, clientFn, serverFn]);
};
export { useTradeSideExecutor };
